package com.acme.notifications

import org.springframework.amqp.rabbit.annotation.RabbitListener
import org.springframework.stereotype.Service
import org.springframework.web.util.UriComponentsBuilder
import java.net.URI
import java.net.URLDecoder
import java.nio.charset.StandardCharsets

data class RedirectEvent(
    val userId: String,
    val targetPath: String,
    val proxyScheme: String?,
    val proxyHost: String?,
    val nonce: String
)

@Service
class RedirectConsumerService(
    private val redirectCache: RedirectCache,
    private val auditLog: AuditLog
) {

    companion object {
        private val ALLOWED_HOSTS = setOf(
            "app.acme.com",
            "portal.acme.com",
            "dashboard.acme.com"
        )
        private val ALLOWED_SCHEMES = setOf("https")
        private const val MAX_PATH_LENGTH = 2048
    }

    @RabbitListener(queues = ["redirect.events"])
    fun handleRedirectEvent(event: RedirectEvent) {
        auditLog.info("Processing redirect for user=${event.userId}, nonce=${event.nonce}")

        val resolvedUrl = resolveRedirectUrl(event)

        if (resolvedUrl != null && isUrlSafe(resolvedUrl)) {
            redirectCache.store(event.nonce, resolvedUrl)
            auditLog.info("Stored redirect nonce=${event.nonce} -> $resolvedUrl")
        } else {
            auditLog.warn("Rejected unsafe redirect for user=${event.userId}: ${event.targetPath}")
            redirectCache.store(event.nonce, "https://app.acme.com/error?code=invalid_redirect")
        }
    }

    private fun resolveRedirectUrl(event: RedirectEvent): String? {
        return try {
            val scheme = event.proxyScheme?.lowercase() ?: "https"
            val host = event.proxyHost ?: "app.acme.com"
            val decodedPath = decodePathSafely(event.targetPath)

            if (decodedPath == null || decodedPath.length > MAX_PATH_LENGTH) {
                return null
            }

            val builder = UriComponentsBuilder.newInstance()
                .scheme(scheme)
                .host(host)
                .path(decodedPath)

            builder.build().toUriString()
        } catch (e: Exception) {
            auditLog.error("Failed to resolve URL for nonce=${event.nonce}", e)
            null
        }
    }

    private fun decodePathSafely(rawPath: String): String? {
        return try {
            // Decode once to handle proxy-encoded paths
            val decoded = URLDecoder.decode(rawPath, StandardCharsets.UTF_8.name())
            // Normalize path separators
            val normalized = decoded.replace("\\", "/")
            // Remove any fragment identifiers from path
            val withoutFragment = normalized.substringBefore("#")
            withoutFragment
        } catch (e: Exception) {
            null
        }
    }

    private fun isUrlSafe(url: String): Boolean {
        return try {
            val uri = URI(url)
            val hostValid = isHostAllowed(uri.host)
            val schemeValid = uri.scheme?.lowercase() in ALLOWED_SCHEMES
            val noUserInfo = uri.userInfo == null
            val pathSafe = !containsPathTraversal(uri.path ?: "")

            hostValid && schemeValid && noUserInfo && pathSafe
        } catch (e: Exception) {
            false
        }
    }

    private fun isHostAllowed(host: String?): Boolean {
        if (host == null) return false
        val normalizedHost = host.lowercase().trim()
        // Check exact match against allowed hosts only
        return normalizedHost in ALLOWED_HOSTS
    }

    private fun containsPathTraversal(path: String): Boolean {
        val normalized = path.replace("\\", "/")
        return normalized.contains("../") || normalized.contains("/..")
    }
}

interface RedirectCache {
    fun store(nonce: String, url: String)
    fun retrieve(nonce: String): String?
}

interface AuditLog {
    fun info(msg: String)
    fun warn(msg: String)
    fun error(msg: String, e: Exception? = null)
}

// Controller that serves the cached redirects
@org.springframework.web.bind.annotation.RestController
class RedirectController(
    private val redirectCache: RedirectCache,
    private val auditLog: AuditLog
) {
    @org.springframework.web.bind.annotation.GetMapping("/r/{nonce}")
    fun performRedirect(
        @org.springframework.web.bind.annotation.PathVariable nonce: String
    ): org.springframework.http.ResponseEntity<Void> {
        val url = redirectCache.retrieve(nonce)
        return if (url != null) {
            auditLog.info("Serving redirect for nonce=$nonce")
            org.springframework.http.ResponseEntity
                .status(org.springframework.http.HttpStatus.FOUND)
                .header("Location", url)
                .build()
        } else {
            org.springframework.http.ResponseEntity.notFound().build()
        }
    }
}
